/**
 * Database enum types (mirrors the Postgres enum types in db/migrations).
 *
 * Replaces the enum types previously generated by Prisma. Each enum has a
 * const array of its values plus a string-literal union type.
 */

export const ROLE_NAME_VALUES = ['OWNER', 'FINANCE', 'ECOMMERCE', 'SALES_REP', 'OPERATIONS'] as const
export type RoleName = (typeof ROLE_NAME_VALUES)[number]

export const INTEGRATION_PROVIDER_VALUES = ['QUICKBOOKS', 'METHOD_CRM', 'SHOPIFY', 'MONDAY'] as const
export type IntegrationProvider = (typeof INTEGRATION_PROVIDER_VALUES)[number]

export const INTEGRATION_STATUS_VALUES = ['NOT_CONFIGURED', 'CONNECTED', 'DEGRADED', 'DISCONNECTED', 'ERROR'] as const
export type IntegrationStatus = (typeof INTEGRATION_STATUS_VALUES)[number]

export const SYNC_TRIGGER_VALUES = ['SCHEDULED', 'MANUAL', 'WEBHOOK', 'BACKFILL', 'RETRY'] as const
export type SyncTrigger = (typeof SYNC_TRIGGER_VALUES)[number]

export const SYNC_STATUS_VALUES = ['QUEUED', 'RUNNING', 'SUCCEEDED', 'PARTIAL', 'FAILED', 'CANCELLED'] as const
export type SyncStatus = (typeof SYNC_STATUS_VALUES)[number]

export const CUSTOMER_CLASSIFICATION_VALUES = ['DIRECT', 'DISTRIBUTOR', 'UNCLASSIFIED'] as const
export type CustomerClassification = (typeof CUSTOMER_CLASSIFICATION_VALUES)[number]

export const INVOICE_STATUS_VALUES = ['DRAFT', 'OPEN', 'PARTIALLY_PAID', 'PAID', 'VOID', 'WRITTEN_OFF'] as const
