export const SHOPIFY_FINANCIAL_STATUS_VALUES = ['PENDING', 'AUTHORIZED', 'PARTIALLY_PAID', 'PAID', 'PARTIALLY_REFUNDED', 'REFUNDED', 'VOIDED', 'UNKNOWN'] as const
export type ShopifyFinancialStatus = (typeof SHOPIFY_FINANCIAL_STATUS_VALUES)[number]

export const SHOPIFY_FULFILLMENT_STATUS_VALUES = ['UNFULFILLED', 'PARTIAL', 'FULFILLED', 'RESTOCKED', 'UNKNOWN'] as const
export type ShopifyFulfillmentStatus = (typeof SHOPIFY_FULFILLMENT_STATUS_VALUES)[number]

export const METRIC_APPROVAL_STATUS_VALUES = ['DRAFT', 'PENDING_APPROVAL', 'APPROVED', 'REJECTED'] as const
export type MetricApprovalStatus = (typeof METRIC_APPROVAL_STATUS_VALUES)[number]

export const BRIEF_STATUS_VALUES = ['PENDING', 'GENERATED', 'SENT', 'PARTIALLY_SENT', 'FAILED'] as const
export type BriefStatus = (typeof BRIEF_STATUS_VALUES)[number]

export const DELIVERY_STATUS_VALUES = ['QUEUED', 'SENT', 'DELIVERED', 'BOUNCED', 'FAILED', 'SUPPRESSED'] as const
export type DeliveryStatus = (typeof DELIVERY_STATUS_VALUES)[number]

export const JOB_STATUS_VALUES = ['PENDING', 'RUNNING', 'SUCCEEDED', 'FAILED', 'DEAD'] as const
